'use strict';

const V = require('./vnext-contract');
const PlanningEnvelope = require('./planning-envelope');
const RequirementRegistry = require('./requirement-registry');
const Impact = require('./impact-graph');
const Plan = require('./plan-contract');
const Review = require('./review-contract');
const Ui = require('./ui-atomicity-contract');
const Preserved = require('./vnext-preserved-controls');

const APPROVAL_TARGET_SCHEMA = 'kodjo.vnext.approval-target.v2';
const APPROVAL_RECORD_SCHEMA = 'kodjo.vnext.approval-record.v2';
const EXECUTION_REQUEST_SCHEMA = 'kodjo.vnext.execution-request.v2';

const APPROVAL_DECISIONS = Object.freeze(['APPROVED', 'REJECTED']);
const APPROVAL_TRANSPORTS = Object.freeze([
  'GITHUB_REACTION',
  'GITHUB_COMMENT',
  'CHATGPT_ACTION',
]);
const IMPLEMENTATION_CHECKS = Object.freeze(['jest', 'typescript', 'lint']);

function validateCurrentHeads(planningEnvelope, currentState) {
  V.assertExactKeys(
    currentState,
    ['product_head', 'application_head', 'protocol_head', 'execution_context', 'native_primitive_decisions'],
    [],
    'VNEXT_HANDOFF_CURRENT_STATE_KEYS_INVALID',
  );
  V.assertSha40(currentState.product_head, 'VNEXT_HANDOFF_PRODUCT_HEAD_INVALID', 'product_head');
  V.assertSha40(currentState.application_head, 'VNEXT_HANDOFF_APPLICATION_HEAD_INVALID', 'application_head');
  V.assertSha40(currentState.protocol_head, 'VNEXT_HANDOFF_PROTOCOL_HEAD_INVALID', 'protocol_head');
  Preserved.validateExecutionContext(currentState.execution_context);
  Preserved.validateNativeShape(currentState.native_primitive_decisions);

  if (currentState.product_head !== planningEnvelope.product_head) {
    V.fail('VNEXT_APPROVAL_PRODUCT_HEAD_STALE');
  }
  if (currentState.application_head !== planningEnvelope.application_head) {
    V.fail('VNEXT_APPROVAL_APPLICATION_HEAD_STALE');
  }
  if (currentState.execution_context.delivery_target
      && currentState.execution_context.delivery_target.application_head !== currentState.application_head) V.fail('VNEXT_DELIVERY_APPLICATION_HEAD_MISMATCH');
  return Object.freeze({
    product_head: currentState.product_head,
    application_head: currentState.application_head,
    protocol_head: currentState.protocol_head,
    execution_context: Preserved.validateExecutionContext(currentState.execution_context),
    native_primitive_decisions: currentState.native_primitive_decisions,
  });
}

function validateApprovedArtifacts({
  planningEnvelope,
  requirementRegistry,
  impactGraph,
  candidateManifest,
  directImportScan,
  planContract,
  reviewContext,
  reviewReport,
  uiAtomicityContract,
}) {
  PlanningEnvelope.validate(planningEnvelope);
  RequirementRegistry.validate(requirementRegistry, planningEnvelope.source_manifest);
  Impact.validateCandidateManifest(candidateManifest);
  Impact.validateImpactGraph(impactGraph, {
    requirementRegistry,
    candidateManifest,
    directImportScan,
  });
  Review.validateReviewContext(reviewContext);
  Review.verifyReviewContext(reviewContext, {
    planningEnvelope, requirementRegistry, impactGraph, candidateManifest,
    directImportScan, planContract, uiAtomicityContract,
  });
  Review.validateReviewReport(reviewReport, reviewContext);

  if (reviewContext.planning_envelope_hash !== planningEnvelope.contract_hash) {
    V.fail('VNEXT_APPROVAL_ENVELOPE_BINDING_MISMATCH');
  }
  if (reviewContext.requirement_registry_hash !== requirementRegistry.contract_hash) {
    V.fail('VNEXT_APPROVAL_REQUIREMENT_REGISTRY_MISMATCH');
  }
  if (reviewContext.candidate_manifest_hash !== candidateManifest.contract_hash) {
    V.fail('VNEXT_APPROVAL_CANDIDATE_MANIFEST_MISMATCH');
  }
  if (reviewContext.impact_graph_hash !== impactGraph.contract_hash) {
    V.fail('VNEXT_APPROVAL_IMPACT_GRAPH_MISMATCH');
  }
  const directScanHash = directImportScan ? directImportScan.contract_hash : null;
  if (reviewContext.direct_import_scan_hash !== directScanHash) {
    V.fail('VNEXT_APPROVAL_DIRECT_SCAN_MISMATCH');
  }
  if (directImportScan) {
    Impact.validateDirectImportScan(directImportScan, candidateManifest);
  }
  if (reviewContext.plan_contract_hash !== planContract.contract_hash) {
    V.fail('VNEXT_APPROVAL_PLAN_CONTEXT_MISMATCH');
  }
  if (reviewReport.plan_contract_hash !== planContract.contract_hash) {
    V.fail('VNEXT_APPROVAL_PLAN_REPORT_MISMATCH');
  }
  if (reviewReport.review_context_hash !== reviewContext.contract_hash) {
    V.fail('VNEXT_APPROVAL_REVIEW_CONTEXT_MISMATCH');
  }
  if (reviewReport.verdict !== 'APPROVE' || reviewReport.blocking_finding_count !== 0) {
    V.fail('VNEXT_APPROVAL_REVIEW_NOT_APPROVED', reviewReport.verdict);
  }

  if (reviewContext.ui_applicable) {
    if (!uiAtomicityContract) V.fail('VNEXT_APPROVAL_UI_CONTRACT_REQUIRED');
    Ui.validateUiAtomicityContract(uiAtomicityContract, {
      requirementRegistry,
      impactGraph,
      candidateManifest,
      planContract,
    });
    if (reviewContext.ui_atomicity_hash !== uiAtomicityContract.contract_hash) {
      V.fail('VNEXT_APPROVAL_UI_CONTEXT_MISMATCH');
    }
    if (reviewReport.ui_atomicity_hash !== uiAtomicityContract.contract_hash) {
      V.fail('VNEXT_APPROVAL_UI_REPORT_MISMATCH');
    }
  } else if (uiAtomicityContract !== null) {
    V.fail('VNEXT_APPROVAL_UI_CONTRACT_UNEXPECTED');
  }
  return true;
}

function buildExecutionCore({
  planningEnvelope,
  requirementRegistry,
  impactGraph,
  candidateManifest,
  directImportScan,
  planContract,
  reviewContext,
  reviewReport,
  uiAtomicityContract = null,
  currentState,
  resolveNativeEvidence = null,
}) {
  Plan.validatePlanContract(planContract, {
    requirementRegistry,
    impactGraph,
    candidateManifest,
  });
  validateApprovedArtifacts({
    planningEnvelope,
    requirementRegistry,
    impactGraph,
    candidateManifest,
    directImportScan,
    planContract,
    reviewContext,
    reviewReport,
    uiAtomicityContract,
  });
  const current = validateCurrentHeads(planningEnvelope, currentState);

  const writeScope = planContract.boundaries.write_scope.map((row) => ({
    candidate_id: row.candidate_id,
    path: row.path,
    change_kind: row.change_kind,
  }));
  const preserveScope = planContract.boundaries.preserve_scope.map((row) => ({
    candidate_id: row.candidate_id,
    path: row.path,
  }));

  return Object.freeze({
    slice_id: planningEnvelope.slice_id,
    issue_id: planningEnvelope.issue_id,
    baseline_head: planningEnvelope.baseline_head,
    product_head: planningEnvelope.product_head,
    application_head: planningEnvelope.application_head,
    protocol_head: current.protocol_head,
    execution_context: current.execution_context,
    native_primitive_decisions: Preserved.buildNativeDecisions(current.native_primitive_decisions, { uiAtomicityContract, requirementRegistry, sourceManifest: planningEnvelope.source_manifest, applicationHead: current.application_head, resolveNativeEvidence }),
    planning_mode: planningEnvelope.planning_mode,
    planning_envelope_hash: planningEnvelope.contract_hash,
    direct_import_scan_hash: directImportScan ? directImportScan.contract_hash : null,
    plan_contract_hash: planContract.contract_hash,
    review_context_hash: reviewContext.contract_hash,
    review_report_hash: reviewReport.contract_hash,
    ui_atomicity_hash: uiAtomicityContract ? uiAtomicityContract.contract_hash : null,
    operation_kind: 'IMPLEMENT',
    write_scope: writeScope,
    preserve_scope: preserveScope,
    forbidden_policy: planContract.boundaries.forbidden_policy,
    checks: [...IMPLEMENTATION_CHECKS],
  });
}

function validateExecutionCore(core) {
  V.assertExactKeys(
    core,
    [
      'slice_id',
      'issue_id',
      'baseline_head',
      'product_head',
      'application_head',
      'protocol_head',
      'planning_mode',
      'execution_context',
      'native_primitive_decisions',
      'planning_envelope_hash',
      'direct_import_scan_hash',
      'plan_contract_hash',
      'review_context_hash',
      'review_report_hash',
      'ui_atomicity_hash',
      'operation_kind',
      'write_scope',
      'preserve_scope',
      'forbidden_policy',
      'checks',
    ],
    [],
    'VNEXT_EXECUTION_CORE_KEYS_INVALID',
  );
  V.assertSliceId(core.slice_id, 'VNEXT_EXECUTION_CORE_SLICE_INVALID');
  Preserved.validateExecutionContext(core.execution_context);
  Preserved.validateNativeShape(core.native_primitive_decisions);
  V.assertUnicodeExactText(core.issue_id, 'VNEXT_EXECUTION_CORE_ISSUE_INVALID', 'issue_id');
  V.assertSha40(core.baseline_head, 'VNEXT_EXECUTION_CORE_BASELINE_INVALID', 'baseline_head');
  V.assertSha40(core.product_head, 'VNEXT_EXECUTION_CORE_PRODUCT_HEAD_INVALID', 'product_head');
  V.assertSha40(core.application_head, 'VNEXT_EXECUTION_CORE_APPLICATION_HEAD_INVALID', 'application_head');
  if (core.execution_context.delivery_target
      && core.execution_context.delivery_target.application_head !== core.application_head) V.fail('VNEXT_DELIVERY_APPLICATION_HEAD_MISMATCH');
  V.assertSha40(core.protocol_head, 'VNEXT_EXECUTION_CORE_PROTOCOL_HEAD_INVALID', 'protocol_head');
  if (!['INITIAL', 'REVISION'].includes(core.planning_mode)) {
    V.fail('VNEXT_EXECUTION_CORE_MODE_INVALID', core.planning_mode);
  }
  for (const [label, value] of [
    ['planning_envelope_hash', core.planning_envelope_hash],
    ['plan_contract_hash', core.plan_contract_hash],
    ['review_context_hash', core.review_context_hash],
    ['review_report_hash', core.review_report_hash],
  ]) {
    V.assertSha64(value, 'VNEXT_EXECUTION_CORE_HASH_INVALID', label);
  }
  if (core.direct_import_scan_hash !== null) {
    V.assertSha64(core.direct_import_scan_hash, 'VNEXT_EXECUTION_CORE_DIRECT_SCAN_HASH_INVALID', 'direct_import_scan_hash');
  }
  if (core.ui_atomicity_hash !== null) {
    V.assertSha64(core.ui_atomicity_hash, 'VNEXT_EXECUTION_CORE_UI_HASH_INVALID', 'ui_atomicity_hash');
  }
  if ((core.ui_atomicity_hash === null) !== (core.native_primitive_decisions.length === 0)) V.fail('VNEXT_NATIVE_CORE_SCOPE_MISMATCH');
  for (const row of core.native_primitive_decisions) {
    V.assertSha64(row.assessment_evidence_hash, 'VNEXT_NATIVE_PROOF_HASH_REQUIRED', 'assessment_evidence_hash');
    V.assertUnicodeExactText(row.assessment_evidence_ref, 'VNEXT_NATIVE_PROOF_REFERENCE_REQUIRED', 'assessment_evidence_ref');
  }
  if (core.operation_kind !== 'IMPLEMENT') V.fail('VNEXT_EXECUTION_CORE_OPERATION_INVALID');
  if (!Array.isArray(core.write_scope) || core.write_scope.length === 0) {
    V.fail('VNEXT_EXECUTION_CORE_WRITE_SCOPE_INVALID');
  }
  const writeIds = new Set();
  for (const row of core.write_scope) {
    V.assertExactKeys(
      row,
      ['candidate_id', 'path', 'change_kind'],
      [],
      'VNEXT_EXECUTION_CORE_WRITE_SCOPE_ROW_INVALID',
    );
    V.assertNonEmptyString(row.candidate_id, 'VNEXT_EXECUTION_CORE_CANDIDATE_ID_INVALID');
    V.assertUnicodeExactText(row.path, 'VNEXT_EXECUTION_CORE_PATH_INVALID', 'write_scope.path');
    if (!['MODIFY', 'CREATE', 'DELETE'].includes(row.change_kind)) {
      V.fail('VNEXT_EXECUTION_CORE_CHANGE_KIND_INVALID', row.change_kind);
    }
    if (writeIds.has(row.candidate_id)) V.fail('VNEXT_EXECUTION_CORE_WRITE_SCOPE_DUPLICATE', row.candidate_id);
    writeIds.add(row.candidate_id);
  }
  if (!Array.isArray(core.preserve_scope)) V.fail('VNEXT_EXECUTION_CORE_PRESERVE_SCOPE_INVALID');
  const preserveIds = new Set();
  for (const row of core.preserve_scope) {
    V.assertExactKeys(
      row,
      ['candidate_id', 'path'],
      [],
      'VNEXT_EXECUTION_CORE_PRESERVE_SCOPE_ROW_INVALID',
    );
    V.assertNonEmptyString(row.candidate_id, 'VNEXT_EXECUTION_CORE_CANDIDATE_ID_INVALID');
    V.assertUnicodeExactText(row.path, 'VNEXT_EXECUTION_CORE_PATH_INVALID', 'preserve_scope.path');
    if (preserveIds.has(row.candidate_id)) V.fail('VNEXT_EXECUTION_CORE_PRESERVE_SCOPE_DUPLICATE', row.candidate_id);
    if (writeIds.has(row.candidate_id)) V.fail('VNEXT_EXECUTION_CORE_SCOPE_OVERLAP', row.candidate_id);
    preserveIds.add(row.candidate_id);
  }
  if (core.forbidden_policy !== 'ALL_OUTSIDE_WRITE_SCOPE') {
    V.fail('VNEXT_EXECUTION_CORE_FORBIDDEN_POLICY_INVALID');
  }
  if (V.canonicalStringify(core.checks) !== V.canonicalStringify(IMPLEMENTATION_CHECKS)) {
    V.fail('VNEXT_EXECUTION_CORE_CHECKS_INVALID');
  }
  return true;
}

function buildApprovalTarget(input) {
  const executionCore = buildExecutionCore(input);
  const executionFingerprint = V.canonicalHash(executionCore);
  return V.sealContract({
    schema_version: APPROVAL_TARGET_SCHEMA,
    approval_target_id: V.stableId('APRT', [
      input.planningEnvelope.slice_id,
      executionFingerprint,
    ]),
    action_expected: 'APPROVE_EXACT_EXECUTION',
    execution_fingerprint: executionFingerprint,
    execution_core: executionCore,
    summary: {
      write_scope_count: executionCore.write_scope.length,
      preserve_scope_count: executionCore.preserve_scope.length,
      check_count: executionCore.checks.length,
    },
  });
}

function validateApprovalTarget(target) {
  V.assertExactKeys(
    target,
    [
      'schema_version',
      'approval_target_id',
      'action_expected',
      'execution_fingerprint',
      'execution_core',
      'summary',
      'contract_hash',
    ],
    [],
    'VNEXT_APPROVAL_TARGET_KEYS_INVALID',
  );
  if (target.schema_version !== APPROVAL_TARGET_SCHEMA) {
    V.fail('VNEXT_APPROVAL_TARGET_SCHEMA_INVALID');
  }
  if (target.action_expected !== 'APPROVE_EXACT_EXECUTION') {
    V.fail('VNEXT_APPROVAL_ACTION_INVALID');
  }
  V.assertSha64(
    target.execution_fingerprint,
    'VNEXT_APPROVAL_EXECUTION_FINGERPRINT_INVALID',
    'execution_fingerprint',
  );
  validateExecutionCore(target.execution_core);
  if (V.canonicalHash(target.execution_core) !== target.execution_fingerprint) {
    V.fail('VNEXT_APPROVAL_EXECUTION_FINGERPRINT_MISMATCH');
  }
  const expectedTargetId = V.stableId('APRT', [
    target.execution_core.slice_id,
    target.execution_fingerprint,
  ]);
  if (target.approval_target_id !== expectedTargetId) {
    V.fail('VNEXT_APPROVAL_TARGET_ID_MISMATCH');
  }
  V.assertExactKeys(
    target.summary,
    ['write_scope_count', 'preserve_scope_count', 'check_count'],
    [],
    'VNEXT_APPROVAL_SUMMARY_KEYS_INVALID',
  );
  if (target.summary.write_scope_count !== target.execution_core.write_scope.length
      || target.summary.preserve_scope_count !== target.execution_core.preserve_scope.length
      || target.summary.check_count !== target.execution_core.checks.length) {
    V.fail('VNEXT_APPROVAL_SUMMARY_MISMATCH');
  }
  V.verifyContractHash(target, 'VNEXT_APPROVAL_TARGET_HASH_MISMATCH');
  return true;
}

function buildApprovalRecord({ approvalTarget, evidence }) {
  validateApprovalTarget(approvalTarget);
  V.assertExactKeys(
    evidence,
    [
      'decision',
      'actor_id',
      'transport',
      'evidence_ref',
      'approved_target_hash',
      'observed_at',
    ],
    ['native_exception_approvals'],
    'VNEXT_APPROVAL_EVIDENCE_KEYS_INVALID',
  );
  if (!APPROVAL_DECISIONS.includes(evidence.decision)) {
    V.fail('VNEXT_APPROVAL_DECISION_INVALID', evidence.decision);
  }
  V.assertUnicodeExactText(evidence.actor_id, 'VNEXT_APPROVAL_ACTOR_INVALID', 'actor_id');
  if (!APPROVAL_TRANSPORTS.includes(evidence.transport)) {
    V.fail('VNEXT_APPROVAL_TRANSPORT_INVALID', evidence.transport);
  }
  V.assertUnicodeExactText(evidence.evidence_ref, 'VNEXT_APPROVAL_EVIDENCE_REF_INVALID', 'evidence_ref');
  V.assertSha64(
    evidence.approved_target_hash,
    'VNEXT_APPROVAL_TARGET_REFERENCE_INVALID',
    'approved_target_hash',
  );
  V.assertIsoDate(evidence.observed_at, 'VNEXT_APPROVAL_OBSERVED_AT_INVALID', 'observed_at');
  if (evidence.approved_target_hash !== approvalTarget.contract_hash) {
    V.fail('VNEXT_APPROVAL_TARGET_REFERENCE_MISMATCH');
  }
  const nativeApprovals = Preserved.validateExceptionApprovals(approvalTarget.execution_core.native_primitive_decisions,
    evidence.native_exception_approvals, evidence.decision);

  return V.sealContract({
    schema_version: APPROVAL_RECORD_SCHEMA,
    approval_record_id: V.stableId('APRV', [
      approvalTarget.contract_hash,
      evidence.actor_id,
      evidence.transport,
      evidence.evidence_ref,
      evidence.decision,
    ]),
    approval_target_hash: approvalTarget.contract_hash,
    execution_fingerprint: approvalTarget.execution_fingerprint,
    decision: evidence.decision,
    actor_id: evidence.actor_id,
    evidence_kind: 'VERIFIED_USER_ACTION',
    transport: evidence.transport,
    evidence_ref: evidence.evidence_ref,
    observed_at: evidence.observed_at,
    native_exception_approvals: nativeApprovals,
  });
}

function validateApprovalRecord(record, approvalTarget) {
  V.assertExactKeys(
    record,
    [
      'schema_version',
      'approval_record_id',
      'approval_target_hash',
      'execution_fingerprint',
      'decision',
      'actor_id',
      'evidence_kind',
      'transport',
      'evidence_ref',
      'observed_at',
      'native_exception_approvals',
      'contract_hash',
    ],
    [],
    'VNEXT_APPROVAL_RECORD_KEYS_INVALID',
  );
  if (record.schema_version !== APPROVAL_RECORD_SCHEMA) {
    V.fail('VNEXT_APPROVAL_RECORD_SCHEMA_INVALID');
  }
  V.verifyContractHash(record, 'VNEXT_APPROVAL_RECORD_HASH_MISMATCH');
  validateApprovalTarget(approvalTarget);
  if (record.approval_target_hash !== approvalTarget.contract_hash) {
    V.fail('VNEXT_APPROVAL_RECORD_TARGET_MISMATCH');
  }
  if (record.execution_fingerprint !== approvalTarget.execution_fingerprint) {
    V.fail('VNEXT_APPROVAL_RECORD_EXECUTION_MISMATCH');
  }
  if (!APPROVAL_DECISIONS.includes(record.decision)) {
    V.fail('VNEXT_APPROVAL_DECISION_INVALID', record.decision);
  }
  V.assertUnicodeExactText(record.actor_id, 'VNEXT_APPROVAL_ACTOR_INVALID', 'actor_id');
  V.assertUnicodeExactText(record.evidence_ref, 'VNEXT_APPROVAL_EVIDENCE_REF_INVALID', 'evidence_ref');
  if (record.evidence_kind !== 'VERIFIED_USER_ACTION') {
    V.fail('VNEXT_APPROVAL_EVIDENCE_KIND_INVALID');
  }
  if (!APPROVAL_TRANSPORTS.includes(record.transport)) {
    V.fail('VNEXT_APPROVAL_TRANSPORT_INVALID', record.transport);
  }
  V.assertIsoDate(record.observed_at, 'VNEXT_APPROVAL_OBSERVED_AT_INVALID', 'observed_at');
  Preserved.validateExceptionApprovals(approvalTarget.execution_core.native_primitive_decisions,
    record.native_exception_approvals, record.decision);
  const expectedRecordId = V.stableId('APRV', [
    approvalTarget.contract_hash,
    record.actor_id,
    record.transport,
    record.evidence_ref,
    record.decision,
  ]);
  if (record.approval_record_id !== expectedRecordId) {
    V.fail('VNEXT_APPROVAL_RECORD_ID_MISMATCH');
  }
  return true;
}

function buildExecutionRequest({
  approvalTarget,
  approvalRecord,
  ...artifacts
}) {
  validateApprovalRecord(approvalRecord, approvalTarget);
  if (approvalRecord.decision !== 'APPROVED') {
    V.fail('VNEXT_HANDOFF_USER_APPROVAL_REQUIRED', approvalRecord.decision);
  }

  const rebuiltTarget = buildApprovalTarget(artifacts);
  if (V.canonicalStringify(rebuiltTarget) !== V.canonicalStringify(approvalTarget)) {
    V.fail('VNEXT_HANDOFF_APPROVAL_STALE');
  }

  const core = rebuiltTarget.execution_core;
  const request = V.sealContract({
    schema_version: EXECUTION_REQUEST_SCHEMA,
    execution_request_id: V.stableId('EXEC', [
      approvalRecord.contract_hash,
      rebuiltTarget.execution_fingerprint,
    ]),
    approval_target_hash: rebuiltTarget.contract_hash,
    approval_record_hash: approvalRecord.contract_hash,
    execution_fingerprint: rebuiltTarget.execution_fingerprint,
    ...core,
  });
  return request;
}

function validateExecutionRequest(request, {
  approvalTarget,
  approvalRecord,
  ...artifacts
}) {
  V.assertExactKeys(
    request,
    [
      'schema_version',
      'execution_request_id',
      'approval_target_hash',
      'approval_record_hash',
      'execution_fingerprint',
      'slice_id',
      'issue_id',
      'baseline_head',
      'product_head',
      'application_head',
      'protocol_head',
      'planning_mode',
      'execution_context',
      'native_primitive_decisions',
      'planning_envelope_hash',
      'direct_import_scan_hash',
      'plan_contract_hash',
      'review_context_hash',
      'review_report_hash',
      'ui_atomicity_hash',
      'operation_kind',
      'write_scope',
      'preserve_scope',
      'forbidden_policy',
      'checks',
      'contract_hash',
    ],
    [],
    'VNEXT_EXECUTION_REQUEST_KEYS_INVALID',
  );
  if (request.schema_version !== EXECUTION_REQUEST_SCHEMA) {
    V.fail('VNEXT_EXECUTION_REQUEST_SCHEMA_INVALID');
  }
  V.verifyContractHash(request, 'VNEXT_EXECUTION_REQUEST_HASH_MISMATCH');
  const rebuilt = buildExecutionRequest({
    approvalTarget,
    approvalRecord,
    ...artifacts,
  });
  if (V.canonicalStringify(rebuilt) !== V.canonicalStringify(request)) {
    V.fail('VNEXT_EXECUTION_REQUEST_REBUILD_MISMATCH');
  }
  return true;
}

function renderApprovalMessage(approvalTarget, { approvalUrl = null } = {}) {
  validateApprovalTarget(approvalTarget);
  if (approvalUrl !== null) {
    V.assertUnicodeExactText(approvalUrl, 'VNEXT_APPROVAL_URL_INVALID', 'approvalUrl');
  }
  const core = approvalTarget.execution_core;
  const lines = [
    '[KODJO_VNEXT] USER_APPROVAL_REQUIRED',
    'approval_target_id=' + approvalTarget.approval_target_id,
    'approval_target_hash=' + approvalTarget.contract_hash,
    'execution_fingerprint=' + approvalTarget.execution_fingerprint,
    'execution_context=' + V.canonicalStringify(core.execution_context),
    'application_head=' + core.application_head,
    'plan_contract_hash=' + core.plan_contract_hash,
    'review_report_hash=' + core.review_report_hash,
    'write_scope_count=' + core.write_scope.length,
    'action_expected=APPROVE_EXACT_EXECUTION',
  ];
  for (const row of core.native_primitive_decisions) lines.push('native_primitive_decision=' + V.canonicalStringify(row));
  for (const id of Preserved.exceptionIds(core.native_primitive_decisions)) lines.push('native_primitive_exception_request=' + id);
  if (Preserved.exceptionIds(core.native_primitive_decisions).length) lines.push('Action requise : autoriser explicitement les exceptions natives listées, ou conserver l’arrêt NATIVE_PRIMITIVE_EXCEPTION_REQUIRED.');
  if (approvalUrl !== null) lines.push('approval_url=' + approvalUrl);
  lines.push(
    '',
    'Action requise : approuver explicitement cet objet exact, ou ne pas approuver.',
  );
  return lines.join('\n');
}

module.exports = {
  APPROVAL_TARGET_SCHEMA,
  APPROVAL_RECORD_SCHEMA,
  EXECUTION_REQUEST_SCHEMA,
  APPROVAL_DECISIONS,
  APPROVAL_TRANSPORTS,
  IMPLEMENTATION_CHECKS,
  validateExecutionCore,
  buildExecutionCore,
  buildApprovalTarget,
  validateApprovalTarget,
  buildApprovalRecord,
  validateApprovalRecord,
  buildExecutionRequest,
  validateExecutionRequest,
  renderApprovalMessage,
};

'use strict';
// A deferred observation remains pending after exact-delivery user approval.
// Technical FAIL/NON_VERIFIABLE is never a device-only gap.
const DEFERABLE_PROOFS = new Set(['VISUAL_COMPARE', 'DEVICE_CHECK', 'ACCESSIBILITY_CHECK']);
function isDeferred(proof) {
  return DEFERABLE_PROOFS.has(proof.proof_type) && proof.status === 'PENDING_DEVICE';
}
function deviceOnlyGap(proofs, gateRequired) {
  return gateRequired && proofs.length > 0 && proofs.some(isDeferred)
    && proofs.every(p => p.status === 'PASS' || isDeferred(p));
}
function effectiveDeviceGate(planned, review) {
  const proofs=[...(review?.criteria||[]).flatMap(row=>[...(row.proof_results||[]),...(row.assertion_results||[]).flatMap(a=>a.proof_results||[])]),
    ...(review?.non_ui_plan_assessment?.requirements||[]).flatMap(row=>row.proof_results||[])];
  return Boolean(planned || proofs.some(proof=>proof.proof_type==='ACCESSIBILITY_CHECK'&&proof.status==='PENDING_DEVICE'));
}
module.exports = { effectiveDeviceGate, DEFERABLE_PROOFS, isDeferred, deviceOnlyGap };

'use strict';

const crypto = require('node:crypto');
const { spawnSync } = require('node:child_process');
const path = require('node:path');

const V = require('./vnext-contract');
const Perf = require('./vnext-performance');
const RequirementRegistry = require('./requirement-registry');
const { normalizeScopeCandidate } = require('./scope-path');
const { extractSpecifiers, resolveSpecifier } = require('./plan-impact');

const CANDIDATE_SCHEMA = 'kodjo.vnext.impact-candidates.v1';
const DIRECT_SCAN_SCHEMA = 'kodjo.vnext.direct-import-scan.v1';
const IMPACT_SCHEMA = 'kodjo.vnext.impact-graph.v1';

const CHANGE_KINDS = Object.freeze(['MODIFY', 'CREATE', 'DELETE', 'NO_CHANGE']);
const EXISTING_CHANGE_KINDS = Object.freeze(['MODIFY', 'DELETE', 'NO_CHANGE']);
const CREATE_CHANGE_KINDS = Object.freeze(['CREATE', 'NO_CHANGE']);
const CREATE_ROOTS = Object.freeze(['app/', 'src/', 'tests/', 'assets/', 'docs/', 'scripts/', '.github/']);
const SOURCE_EXTENSIONS = Object.freeze(['.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs']);

function git(args, cwd, encoding = 'utf8', input) {
  const result = Perf.measure('git.' + args[0], () => spawnSync('git', args, {
    cwd,
    encoding,
    windowsHide: true,
    shell: false,
    maxBuffer: 64 * 1024 * 1024,
    input: encoding === 'buffer' && typeof input === 'string' ? Buffer.from(input, 'utf8') : input,
  }));
  if (result.error || result.status !== 0) {
    V.fail(
      'VNEXT_IMPACT_GIT_FAILED',
      `git ${args.join(' ')}: ${String(result.stderr || result.error?.message || '').trim()}`,
    );
  }
  return result.stdout;
}

function normalizeRepoPath(value, code = 'VNEXT_IMPACT_PATH_INVALID', label = 'path') {
  const normalized = normalizeScopeCandidate(value);
  if (!normalized || normalized !== value) V.fail(code, `${label}=${String(value)}`);
  V.assertUnicodeExactText(normalized, code, label);
  return normalized;
}

function candidateKind(file) {
  if (/(?:^|\/)(?:__tests__|tests?)\//.test(file) || /\.(?:test|spec)\.[^.]+$/.test(file)) return 'TEST';
  if (file.startsWith('.github/')) return 'WORKFLOW';
  if (file.startsWith('docs/') || file.endsWith('.md')) return 'DOCUMENTATION';
  if (file.startsWith('assets/')) return 'ASSET';
  if (SOURCE_EXTENSIONS.some((ext) => file.endsWith(ext)) || /\.(?:json|ya?ml|ps1|py|sh)$/.test(file)) return 'CODE';
  return 'OTHER';
}

function validateCreateSlot(slot, revision, existingFiles, index) {
  V.assertExactKeys(
    slot,
    ['path', 'policy_id', 'policy_hash'],
    [],
    'VNEXT_CREATE_SLOT_KEYS_INVALID',
  );
  const repoPath = normalizeRepoPath(slot.path, 'VNEXT_CREATE_SLOT_PATH_INVALID', `create_slots[${index}].path`);
  if (!CREATE_ROOTS.some((root) => repoPath.startsWith(root))) {
    V.fail('VNEXT_CREATE_SLOT_ROOT_FORBIDDEN', repoPath);
  }
  if (existingFiles.has(repoPath)) V.fail('VNEXT_CREATE_SLOT_ALREADY_EXISTS', repoPath);
  V.assertNonEmptyString(slot.policy_id, 'VNEXT_CREATE_SLOT_POLICY_INVALID', 'policy_id');
  V.assertSha64(slot.policy_hash, 'VNEXT_CREATE_SLOT_POLICY_HASH_INVALID', 'policy_hash');
  return Object.freeze({
    candidate_id: V.stableId('CAND', [revision, 'CREATE_SLOT', repoPath, slot.policy_id, slot.policy_hash]),
    path: repoPath,
    candidate_kind: 'CREATE_SLOT',
    origin: 'CREATE_SLOT_POLICY',
    policy_id: slot.policy_id,
    policy_hash: slot.policy_hash,
    allowed_change_kinds: [...CREATE_CHANGE_KINDS],
  });
}

function buildCandidateManifest({ cwd = process.cwd(), revision, createSlots = [] }) {
  V.assertSha40(revision, 'VNEXT_IMPACT_REVISION_INVALID', 'revision');
  git(['cat-file', '-e', revision + '^{commit}'], cwd);

  const rawTree = git(['ls-tree', '-r', '-z', revision], cwd, 'buffer');
  const treeSha256 = crypto.createHash('sha256').update(rawTree).digest('hex');
  const rawNames = git(['ls-tree', '-r', '--name-only', '-z', revision], cwd, 'buffer');
  const files = rawNames.toString('utf8').split('\0').filter(Boolean)
    .map((file) => normalizeRepoPath(file))
    .sort();

  const fileSet = new Set(files);
  const candidates = files.map((file) => Object.freeze({
    candidate_id: V.stableId('CAND', [revision, 'EXISTING_FILE', file]),
    path: file,
    candidate_kind: candidateKind(file),
    origin: 'GIT_TREE',
    policy_id: null,
    policy_hash: null,
    allowed_change_kinds: [...EXISTING_CHANGE_KINDS],
  }));

  if (!Array.isArray(createSlots)) V.fail('VNEXT_CREATE_SLOTS_INVALID');
  for (let index = 0; index < createSlots.length; index += 1) {
    candidates.push(validateCreateSlot(createSlots[index], revision, fileSet, index));
  }

  candidates.sort((a, b) => a.path.localeCompare(b.path) || a.origin.localeCompare(b.origin));
  const ids = candidates.map((candidate) => candidate.candidate_id);
  if (new Set(ids).size !== ids.length) V.fail('VNEXT_IMPACT_CANDIDATE_ID_DUPLICATE');
  const pathOrigin = candidates.map((candidate) => `${candidate.origin}\u0000${candidate.path}`);
  if (new Set(pathOrigin).size !== pathOrigin.length) V.fail('VNEXT_IMPACT_CANDIDATE_DUPLICATE');

  return V.sealContract({
    schema_version: CANDIDATE_SCHEMA,
    revision,
    git_tree_sha256: treeSha256,
    candidate_count: candidates.length,
    candidates,
  });
}

function validateCandidateManifest(manifest) {
  V.assertExactKeys(
    manifest,
    ['schema_version', 'revision', 'git_tree_sha256', 'candidate_count', 'candidates', 'contract_hash'],
    [],
    'VNEXT_IMPACT_CANDIDATE_MANIFEST_KEYS_INVALID',
  );
  if (manifest.schema_version !== CANDIDATE_SCHEMA) {
    V.fail('VNEXT_IMPACT_CANDIDATE_SCHEMA_INVALID', manifest.schema_version);
  }
  V.assertSha40(manifest.revision, 'VNEXT_IMPACT_REVISION_INVALID', 'revision');
  V.assertSha64(manifest.git_tree_sha256, 'VNEXT_IMPACT_TREE_HASH_INVALID', 'git_tree_sha256');
  V.verifyContractHash(manifest, 'VNEXT_IMPACT_CANDIDATE_HASH_MISMATCH');
  if (!Array.isArray(manifest.candidates) || manifest.candidate_count !== manifest.candidates.length) {
    V.fail('VNEXT_IMPACT_CANDIDATE_COUNT_MISMATCH');
  }
  const ids = new Set();
  for (const candidate of manifest.candidates) {
    V.assertExactKeys(
      candidate,
      [
        'candidate_id', 'path', 'candidate_kind', 'origin', 'policy_id', 'policy_hash',
        'allowed_change_kinds',
      ],
      [],
      'VNEXT_IMPACT_CANDIDATE_KEYS_INVALID',
    );
    normalizeRepoPath(candidate.path);
    if (ids.has(candidate.candidate_id)) V.fail('VNEXT_IMPACT_CANDIDATE_ID_DUPLICATE', candidate.candidate_id);
    ids.add(candidate.candidate_id);
    const expectedId = candidate.origin === 'GIT_TREE'
      ? V.stableId('CAND', [manifest.revision, 'EXISTING_FILE', candidate.path])
      : V.stableId('CAND', [
        manifest.revision, 'CREATE_SLOT', candidate.path, candidate.policy_id, candidate.policy_hash,
      ]);
    if (candidate.candidate_id !== expectedId) V.fail('VNEXT_IMPACT_CANDIDATE_ID_MISMATCH', candidate.candidate_id);
    if (candidate.origin === 'GIT_TREE') {
      if (candidate.candidate_kind !== candidateKind(candidate.path)) {
        V.fail('VNEXT_IMPACT_CANDIDATE_KIND_MISMATCH', candidate.path);
      }
      if (candidate.policy_id !== null || candidate.policy_hash !== null) V.fail('VNEXT_IMPACT_GIT_CANDIDATE_POLICY_FORBIDDEN');
      if (V.canonicalStringify(candidate.allowed_change_kinds) !== V.canonicalStringify(EXISTING_CHANGE_KINDS)) {
        V.fail('VNEXT_IMPACT_EXISTING_CHANGE_KINDS_INVALID', candidate.path);
      }
    } else if (candidate.origin === 'CREATE_SLOT_POLICY') {
      if (candidate.candidate_kind !== 'CREATE_SLOT') V.fail('VNEXT_IMPACT_CREATE_SLOT_KIND_INVALID', candidate.path);
      if (!CREATE_ROOTS.some((root) => candidate.path.startsWith(root))) {
        V.fail('VNEXT_CREATE_SLOT_ROOT_FORBIDDEN', candidate.path);
      }
      V.assertNonEmptyString(candidate.policy_id, 'VNEXT_CREATE_SLOT_POLICY_INVALID', 'policy_id');
      V.assertSha64(candidate.policy_hash, 'VNEXT_CREATE_SLOT_POLICY_HASH_INVALID', 'policy_hash');
      if (V.canonicalStringify(candidate.allowed_change_kinds) !== V.canonicalStringify(CREATE_CHANGE_KINDS)) {
        V.fail('VNEXT_IMPACT_CREATE_CHANGE_KINDS_INVALID', candidate.path);
      }
    } else {
      V.fail('VNEXT_IMPACT_CANDIDATE_ORIGIN_INVALID', candidate.origin);
    }
  }
  return true;
}

function verifyCandidateManifestAtHead(manifest, { cwd = process.cwd() } = {}) {
  validateCandidateManifest(manifest);
  git(['cat-file', '-e', manifest.revision + '^{commit}'], cwd);
  const rawTree = git(['ls-tree', '-r', '-z', manifest.revision], cwd, 'buffer');
  const currentHash = crypto.createHash('sha256').update(rawTree).digest('hex');
  if (currentHash !== manifest.git_tree_sha256) V.fail('VNEXT_IMPACT_TREE_DRIFT');
  const tracked = new Set(
    git(['ls-tree', '-r', '--name-only', '-z', manifest.revision], cwd, 'buffer')
      .toString('utf8').split('\0').filter(Boolean).map((file) => normalizeRepoPath(file)),
  );
  for (const candidate of manifest.candidates) {
    if (candidate.origin === 'GIT_TREE' && !tracked.has(candidate.path)) {
      V.fail('VNEXT_IMPACT_EXISTING_PATH_ABSENT', candidate.path);
    }
    if (candidate.origin === 'CREATE_SLOT_POLICY' && tracked.has(candidate.path)) {
      V.fail('VNEXT_CREATE_SLOT_ALREADY_EXISTS', candidate.path);
    }
  }
  return true;
}

function scanOneLevelDirectImporters({
  cwd = process.cwd(),
  candidateManifest,
  modifyCandidateIds,
}) {
  validateCandidateManifest(candidateManifest);
  if (!Array.isArray(modifyCandidateIds) || modifyCandidateIds.length === 0) {
    V.fail('VNEXT_DIRECT_IMPORT_TARGETS_EMPTY');
  }
  if (new Set(modifyCandidateIds).size !== modifyCandidateIds.length) {
    V.fail('VNEXT_DIRECT_IMPORT_TARGET_DUPLICATE');
  }

  const byId = new Map(candidateManifest.candidates.map((candidate) => [candidate.candidate_id, candidate]));
  const targets = modifyCandidateIds.map((id) => {
    const candidate = byId.get(id);
    if (!candidate) V.fail('VNEXT_DIRECT_IMPORT_TARGET_UNKNOWN', id);
    if (candidate.origin !== 'GIT_TREE') V.fail('VNEXT_DIRECT_IMPORT_TARGET_NOT_EXISTING', id);
    if (!SOURCE_EXTENSIONS.some((ext) => candidate.path.endsWith(ext))) {
      V.fail('VNEXT_DIRECT_IMPORT_TARGET_NOT_SOURCE', candidate.path);
    }
    return candidate;
  });
  const targetPathSet = new Set(targets.map((target) => target.path));
  const fileSet = new Set(
    candidateManifest.candidates
      .filter((candidate) => candidate.origin === 'GIT_TREE')
      .map((candidate) => candidate.path),
  );
  const idByPath = new Map(
    candidateManifest.candidates
      .filter((candidate) => candidate.origin === 'GIT_TREE')
      .map((candidate) => [candidate.path, candidate.candidate_id]),
  );

  const importers = [];
  const sourceFiles = [...fileSet]
    .filter((file) => SOURCE_EXTENSIONS.some((ext) => file.endsWith(ext)))
    .sort();

  const scannedFiles = sourceFiles.filter(file => !targetPathSet.has(file));
  const contents = Perf.measure('impact.read-source-blobs', () => require('./vnext-git-batch').readBlobs({
    revision: candidateManifest.revision, files: scannedFiles,
    run: (args, input) => git(args, cwd, 'buffer', input),
  }), { files: scannedFiles.length });
  for (const file of scannedFiles) {
    const source = contents.get(file).toString('utf8');
    const triggeredPaths = extractSpecifiers(source)
      .map((specifier) => resolveSpecifier(file, specifier, fileSet))
      .filter((resolved) => resolved && targetPathSet.has(resolved));
    const uniquePaths = [...new Set(triggeredPaths)].sort();
    if (uniquePaths.length === 0) continue;

    importers.push({
      candidate_id: idByPath.get(file),
      path: file,
      candidate_kind: candidateKind(file),
      triggered_by_candidate_ids: uniquePaths.map((targetPath) => idByPath.get(targetPath)).sort(),
    });
  }

  importers.sort((a, b) => a.path.localeCompare(b.path));
  return V.sealContract({
    schema_version: DIRECT_SCAN_SCHEMA,
    revision: candidateManifest.revision,
    candidate_manifest_hash: candidateManifest.contract_hash,
    target_candidate_ids: [...modifyCandidateIds].sort(),
    importer_count: importers.length,
    importers,
  });
}

function validateDirectImportScan(scan, candidateManifest) {
  V.assertExactKeys(
    scan,
    [
      'schema_version', 'revision', 'candidate_manifest_hash', 'target_candidate_ids',
      'importer_count', 'importers', 'contract_hash',
    ],
    [],
    'VNEXT_DIRECT_IMPORT_SCAN_KEYS_INVALID',
  );
  if (scan.schema_version !== DIRECT_SCAN_SCHEMA) V.fail('VNEXT_DIRECT_IMPORT_SCAN_SCHEMA_INVALID');
  V.verifyContractHash(scan, 'VNEXT_DIRECT_IMPORT_SCAN_HASH_MISMATCH');
  validateCandidateManifest(candidateManifest);
  if (scan.revision !== candidateManifest.revision) V.fail('VNEXT_DIRECT_IMPORT_SCAN_REVISION_MISMATCH');
  if (scan.candidate_manifest_hash !== candidateManifest.contract_hash) {
    V.fail('VNEXT_DIRECT_IMPORT_CANDIDATE_MANIFEST_MISMATCH');
  }
  if (!Array.isArray(scan.importers) || scan.importer_count !== scan.importers.length) {
    V.fail('VNEXT_DIRECT_IMPORT_COUNT_MISMATCH');
  }
  return true;
}

function verifyDirectImportScanAtHead(scan, candidateManifest, { cwd = process.cwd() } = {}) {
  verifyCandidateManifestAtHead(candidateManifest, { cwd });
  validateDirectImportScan(scan, candidateManifest);
  const rebuilt = scanOneLevelDirectImporters({
    cwd, candidateManifest, modifyCandidateIds: scan.target_candidate_ids,
  });
  if (V.canonicalStringify(scan) !== V.canonicalStringify(rebuilt)) {
    V.fail('VNEXT_DIRECT_IMPORT_SCAN_REBUILD_MISMATCH');
  }
  return true;
}

function classificationKey(requirementId, candidateId) {
  return `${requirementId}\u0000${candidateId === null ? '<NO_TARGET>' : candidateId}`;
}

function normalizeClassification(row, index, requirementIds, candidateById) {
  V.assertExactKeys(
    row,
    [
      'requirement_id', 'candidate_id', 'change_kind', 'impact_reason',
      'dependency_evidence', 'tests_affected_candidate_ids', 'preservation_candidate_ids',
    ],
    [],
    'VNEXT_IMPACT_CLASSIFICATION_KEYS_INVALID',
  );
  if (!requirementIds.has(row.requirement_id)) V.fail('VNEXT_IMPACT_REQUIREMENT_UNKNOWN', row.requirement_id);
  if (!CHANGE_KINDS.includes(row.change_kind)) V.fail('VNEXT_IMPACT_CHANGE_KIND_INVALID', row.change_kind);
  V.assertUnicodeExactText(row.impact_reason, 'VNEXT_IMPACT_REASON_INVALID', `classifications[${index}].impact_reason`);
  const dependencyEvidence = V.uniqueStrings(
    row.dependency_evidence,
    'VNEXT_IMPACT_DEPENDENCY_EVIDENCE_INVALID',
    `classifications[${index}].dependency_evidence`,
    { allowEmpty: row.change_kind === 'NO_CHANGE' },
  );
  const testsAffected = V.uniqueStrings(
    row.tests_affected_candidate_ids,
    'VNEXT_IMPACT_TEST_IDS_INVALID',
    `classifications[${index}].tests_affected_candidate_ids`,
    { allowEmpty: true },
  );
  const preservation = V.uniqueStrings(
    row.preservation_candidate_ids,
    'VNEXT_IMPACT_PRESERVATION_IDS_INVALID',
    `classifications[${index}].preservation_candidate_ids`,
    { allowEmpty: true },
  );

  if (row.candidate_id === null) {
    if (row.change_kind !== 'NO_CHANGE') V.fail('VNEXT_IMPACT_NULL_TARGET_ONLY_NO_CHANGE');
    if (testsAffected.length || preservation.length) V.fail('VNEXT_IMPACT_NULL_TARGET_EDGES_FORBIDDEN');
  } else {
    V.assertNonEmptyString(row.candidate_id, 'VNEXT_IMPACT_CANDIDATE_ID_INVALID', 'candidate_id');
    const candidate = candidateById.get(row.candidate_id);
    if (!candidate) V.fail('VNEXT_IMPACT_CANDIDATE_UNKNOWN', row.candidate_id);
    if (!candidate.allowed_change_kinds.includes(row.change_kind)) {
      V.fail('VNEXT_IMPACT_CHANGE_KIND_NOT_ALLOWED', `${candidate.path}:${row.change_kind}`);
    }
  }

  for (const id of [...testsAffected, ...preservation]) {
    if (!candidateById.has(id)) V.fail('VNEXT_IMPACT_EDGE_CANDIDATE_UNKNOWN', id);
  }

  return {
    requirement_id: row.requirement_id,
    candidate_id: row.candidate_id,
    change_kind: row.change_kind,
    impact_reason: row.impact_reason,
    dependency_evidence: dependencyEvidence,
    tests_affected_candidate_ids: testsAffected,
    preservation_candidate_ids: preservation,
  };
}

function buildImpactGraph({
  requirementRegistry,
  candidateManifest,
  classifications,
  directImportScan = null,
}) {
  RequirementRegistry.assertReady(requirementRegistry);
  validateCandidateManifest(candidateManifest);
  if (!Array.isArray(classifications)) V.fail('VNEXT_IMPACT_CLASSIFICATIONS_INVALID');

  const requirementIds = new Set(requirementRegistry.requirements.map((req) => req.requirement_id));
  const candidateById = new Map(candidateManifest.candidates.map((candidate) => [candidate.candidate_id, candidate]));
  const normalized = classifications.map((row, index) =>
    normalizeClassification(row, index, requirementIds, candidateById));

  const seen = new Set();
  for (const row of normalized) {
    const key = classificationKey(row.requirement_id, row.candidate_id);
    if (seen.has(key)) V.fail('VNEXT_IMPACT_CLASSIFICATION_DUPLICATE', key);
    seen.add(key);
  }

  const rowsByRequirement = new Map();
  for (const reqId of requirementIds) rowsByRequirement.set(reqId, []);
  for (const row of normalized) rowsByRequirement.get(row.requirement_id).push(row);

  for (const [reqId, rows] of rowsByRequirement) {
    if (rows.length === 0) V.fail('VNEXT_IMPACT_REQUIREMENT_UNCOVERED', reqId);
    const targetlessNoChange = rows.filter((row) => row.candidate_id === null && row.change_kind === 'NO_CHANGE');
    if (targetlessNoChange.length > 1) V.fail('VNEXT_IMPACT_NO_CHANGE_DUPLICATE', reqId);
    if (targetlessNoChange.length === 1 && rows.length !== 1) {
      V.fail('VNEXT_IMPACT_NO_CHANGE_MIXED_WITH_TARGETS', reqId);
    }
  }

  const selectedModifyIds = [...new Set(
    normalized
      .filter((row) => row.change_kind === 'MODIFY' && row.candidate_id !== null)
      .map((row) => row.candidate_id),
  )].sort();
  const selectedDirectRootIds = selectedModifyIds.filter((id) => {
    const candidate = candidateById.get(id);
    return candidate
      && candidate.origin === 'GIT_TREE'
      && candidate.candidate_kind === 'CODE'
      && SOURCE_EXTENSIONS.some((ext) => candidate.path.endsWith(ext));
  });

  if (selectedDirectRootIds.length > 0) {
    if (!directImportScan) V.fail('VNEXT_DIRECT_IMPORT_SCAN_REQUIRED');
    validateDirectImportScan(directImportScan, candidateManifest);
    if (V.canonicalStringify(directImportScan.target_candidate_ids) !== V.canonicalStringify(selectedDirectRootIds)) {
      V.fail('VNEXT_DIRECT_IMPORT_TARGET_SET_MISMATCH');
    }

    const modifiedByRequirement = new Map();
    for (const row of normalized.filter((item) => item.change_kind === 'MODIFY')) {
      const set = modifiedByRequirement.get(row.requirement_id) || new Set();
      set.add(row.candidate_id);
      modifiedByRequirement.set(row.requirement_id, set);
    }

    for (const importer of directImportScan.importers) {
      for (const [reqId, targetIds] of modifiedByRequirement) {
        const relevant = importer.triggered_by_candidate_ids.some((id) => targetIds.has(id));
        if (!relevant) continue;
        const key = classificationKey(reqId, importer.candidate_id);
        if (!seen.has(key)) {
          V.fail('VNEXT_DIRECT_IMPORT_CLASSIFICATION_MISSING', `${reqId}:${importer.path}`);
        }
      }
    }
  } else if (directImportScan !== null) {
    V.fail('VNEXT_DIRECT_IMPORT_SCAN_UNEXPECTED');
  }

  const directByCandidate = new Map();
  if (directImportScan) {
    for (const importer of directImportScan.importers) {
      directByCandidate.set(importer.candidate_id, importer.triggered_by_candidate_ids);
    }
  }

  const impacts = normalized.map((row) => {
    const candidate = row.candidate_id === null ? null : candidateById.get(row.candidate_id);
    return {
      impact_id: V.stableId('IMP', [row.requirement_id, row.candidate_id, row.change_kind]),
      requirement_id: row.requirement_id,
      candidate_id: row.candidate_id,
      target_id: row.candidate_id,
      path: candidate ? candidate.path : null,
      target_kind: candidate ? candidate.candidate_kind : 'NO_TARGET',
      change_kind: row.change_kind,
      candidate_origin: candidate ? candidate.origin : 'REQUIREMENT_LEVEL',
      impact_reason: row.impact_reason,
      dependency_evidence: row.dependency_evidence,
      direct_import_trigger_ids: row.candidate_id && directByCandidate.has(row.candidate_id)
        ? [...directByCandidate.get(row.candidate_id)]
        : [],
      tests_affected_candidate_ids: row.tests_affected_candidate_ids,
      preservation_candidate_ids: row.preservation_candidate_ids,
    };
  }).sort((a, b) =>
    a.requirement_id.localeCompare(b.requirement_id)
      || String(a.path).localeCompare(String(b.path))
      || a.change_kind.localeCompare(b.change_kind));

  return V.sealContract({
    schema_version: IMPACT_SCHEMA,
    requirement_registry_hash: requirementRegistry.contract_hash,
    candidate_manifest_hash: candidateManifest.contract_hash,
    direct_import_scan_hash: directImportScan ? directImportScan.contract_hash : null,
    impact_count: impacts.length,
    requirement_count: requirementIds.size,
    impacts,
  });
}

function validateImpactGraph(graph, { requirementRegistry, candidateManifest, directImportScan = null }) {
  V.assertExactKeys(
    graph,
    [
      'schema_version', 'requirement_registry_hash', 'candidate_manifest_hash',
      'direct_import_scan_hash', 'impact_count', 'requirement_count', 'impacts', 'contract_hash',
    ],
    [],
    'VNEXT_IMPACT_GRAPH_KEYS_INVALID',
  );
  if (graph.schema_version !== IMPACT_SCHEMA) V.fail('VNEXT_IMPACT_GRAPH_SCHEMA_INVALID');
  V.verifyContractHash(graph, 'VNEXT_IMPACT_GRAPH_HASH_MISMATCH');
  if (graph.requirement_registry_hash !== requirementRegistry.contract_hash) {
    V.fail('VNEXT_IMPACT_REQUIREMENT_REGISTRY_HASH_MISMATCH');
  }
  if (graph.candidate_manifest_hash !== candidateManifest.contract_hash) {
    V.fail('VNEXT_IMPACT_CANDIDATE_MANIFEST_HASH_MISMATCH');
  }
  const expectedDirectHash = directImportScan ? directImportScan.contract_hash : null;
  if (graph.direct_import_scan_hash !== expectedDirectHash) V.fail('VNEXT_IMPACT_DIRECT_SCAN_HASH_MISMATCH');

  const classifications = graph.impacts.map((impact) => ({
    requirement_id: impact.requirement_id,
    candidate_id: impact.candidate_id,
    change_kind: impact.change_kind,
    impact_reason: impact.impact_reason,
    dependency_evidence: impact.dependency_evidence,
    tests_affected_candidate_ids: impact.tests_affected_candidate_ids,
    preservation_candidate_ids: impact.preservation_candidate_ids,
  }));
  const rebuilt = buildImpactGraph({
    requirementRegistry,
    candidateManifest,
    classifications,
    directImportScan,
  });
  if (V.canonicalStringify(rebuilt) !== V.canonicalStringify(graph)) {
    V.fail('VNEXT_IMPACT_GRAPH_REBUILD_MISMATCH');
  }
  return true;
}

module.exports = {
  verifyDirectImportScanAtHead,
  CANDIDATE_SCHEMA,
  DIRECT_SCAN_SCHEMA,
  IMPACT_SCHEMA,
  CHANGE_KINDS,
  CREATE_ROOTS,
  buildCandidateManifest,
  validateCandidateManifest,
  verifyCandidateManifestAtHead,
  scanOneLevelDirectImporters,
  validateDirectImportScan,
  buildImpactGraph,
  validateImpactGraph,
};

