'use strict';

const V = require('./vnext-contract');
const SourceManifest = require('./source-manifest');

const SCHEMA = 'kodjo.vnext.planning-envelope.v1';
const MODES = Object.freeze(['INITIAL', 'REVISION']);
const CREATED_FROM_KINDS = Object.freeze(['INITIAL_REQUEST', 'PLAN_REVIEW_REVISE', 'CLARIFICATION_RESOLVED', 'ACCEPTANCE_GAPS']);

function validateCreatedFrom(value) {
  V.assertExactKeys(value, ['kind', 'refs'], [], 'VNEXT_CREATED_FROM_KEYS_INVALID');
  if (!CREATED_FROM_KINDS.includes(value.kind)) V.fail('VNEXT_CREATED_FROM_KIND_INVALID', value.kind);
  return Object.freeze({ kind: value.kind, refs: V.uniqueStrings(value.refs, 'VNEXT_CREATED_FROM_REFS_INVALID', 'created_from.refs') });
}

function build(input) {
  V.assertExactKeys(input, [
    'slice_id', 'planning_mode', 'baseline_head', 'product_head', 'application_head', 'issue_id',
    'source_manifest', 'base_plan_hash', 'base_review_hash', 'causal_findings', 'created_from',
  ], [], 'VNEXT_PLANNING_ENVELOPE_INPUT_INVALID');

  V.assertSliceId(input.slice_id);
  if (!MODES.includes(input.planning_mode)) V.fail('VNEXT_PLANNING_MODE_INVALID', input.planning_mode);
  V.assertSha40(input.baseline_head, 'VNEXT_BASELINE_HEAD_INVALID', 'baseline_head');
  V.assertSha40(input.product_head, 'VNEXT_PRODUCT_HEAD_INVALID', 'product_head');
  V.assertSha40(input.application_head, 'VNEXT_APPLICATION_HEAD_INVALID', 'application_head');
  V.assertUnicodeExactText(input.issue_id, 'VNEXT_ISSUE_ID_INVALID', 'issue_id');
  SourceManifest.validate(input.source_manifest);
  if (input.source_manifest.slice_id !== input.slice_id) V.fail('VNEXT_SOURCE_MANIFEST_SLICE_MISMATCH');
  if (input.source_manifest.product_head !== input.product_head) V.fail('VNEXT_SOURCE_MANIFEST_HEAD_MISMATCH');
  const createdFrom = validateCreatedFrom(input.created_from);

  let basePlanHash = input.base_plan_hash;
  let baseReviewHash = input.base_review_hash;
  let causalFindings = input.causal_findings;

  if (input.planning_mode === 'INITIAL') {
    if (basePlanHash !== null || baseReviewHash !== null) V.fail('VNEXT_INITIAL_CAUSAL_BASE_FORBIDDEN');
    if (!Array.isArray(causalFindings) || causalFindings.length !== 0) V.fail('VNEXT_INITIAL_FINDINGS_FORBIDDEN');
    if (createdFrom.kind !== 'INITIAL_REQUEST') V.fail('VNEXT_INITIAL_CREATED_FROM_INVALID');
  } else {
    V.assertSha64(basePlanHash, 'VNEXT_REVISION_BASE_PLAN_INVALID', 'base_plan_hash');
    V.assertSha64(baseReviewHash, 'VNEXT_REVISION_BASE_REVIEW_INVALID', 'base_review_hash');
    if (createdFrom.kind === 'ACCEPTANCE_GAPS') {
      if (!Array.isArray(causalFindings) || causalFindings.length) V.fail('VNEXT_ACCEPTANCE_REVIEW_FINDINGS_FORBIDDEN');
    } else causalFindings = V.uniqueStrings(causalFindings, 'VNEXT_REVISION_FINDINGS_INVALID', 'causal_findings');
    if (!['PLAN_REVIEW_REVISE', 'CLARIFICATION_RESOLVED', 'ACCEPTANCE_GAPS'].includes(createdFrom.kind)) {
      V.fail('VNEXT_REVISION_CREATED_FROM_INVALID', createdFrom.kind);
    }
  }

  return V.sealContract({
    schema_version: SCHEMA,
    slice_id: input.slice_id,
    planning_mode: input.planning_mode,
    baseline_head: input.baseline_head,
    product_head: input.product_head,
    application_head: input.application_head,
    issue_id: input.issue_id,
    source_manifest: input.source_manifest,
    base_plan_hash: basePlanHash,
    base_review_hash: baseReviewHash,
    causal_findings: causalFindings,
    created_from: createdFrom,
  });
}

function validate(envelope) {
  V.assertExactKeys(envelope, [
    'schema_version', 'slice_id', 'planning_mode', 'baseline_head', 'product_head', 'application_head', 'issue_id',
    'source_manifest', 'base_plan_hash', 'base_review_hash', 'causal_findings', 'created_from', 'contract_hash',
  ], [], 'VNEXT_PLANNING_ENVELOPE_KEYS_INVALID');
  if (envelope.schema_version !== SCHEMA) V.fail('VNEXT_PLANNING_ENVELOPE_SCHEMA_INVALID', envelope.schema_version);
  V.verifyContractHash(envelope, 'VNEXT_PLANNING_ENVELOPE_HASH_MISMATCH');
  const rebuilt = build({
    slice_id: envelope.slice_id, planning_mode: envelope.planning_mode, baseline_head: envelope.baseline_head,
    product_head: envelope.product_head, application_head: envelope.application_head, issue_id: envelope.issue_id,
    source_manifest: envelope.source_manifest, base_plan_hash: envelope.base_plan_hash, base_review_hash: envelope.base_review_hash,
    causal_findings: envelope.causal_findings, created_from: envelope.created_from,
  });
  if (V.canonicalStringify(rebuilt) !== V.canonicalStringify(envelope)) V.fail('VNEXT_PLANNING_ENVELOPE_REBUILD_MISMATCH');
  return true;
}

module.exports = { SCHEMA, MODES, CREATED_FROM_KINDS, build, validate };

'use strict';

const crypto = require('node:crypto');

const SCHEMA = 'kodjo.protocol.v2.queue-preflight.v1';
const CHECK_STATUSES = new Set(['PASS','FAIL','BLOCKED','NOT_APPLICABLE']);

function canonical(value) {
  if (Array.isArray(value)) return '[' + value.map(canonical).join(',') + ']';
  if (value && typeof value === 'object') {
    return '{' + Object.keys(value).sort().map((k) => JSON.stringify(k) + ':' + canonical(value[k])).join(',') + '}';
  }
  return JSON.stringify(value);
}
function sha256(value) {
  const input = Buffer.isBuffer(value) ? value : Buffer.from(typeof value === 'string' ? value : canonical(value), 'utf8');
  return crypto.createHash('sha256').update(input).digest('hex');
}
function normalizedChecks(checks) {
  return [...checks].map((row) => ({
    id:String(row.id),
    status:String(row.status),
    source:String(row.source || ''),
    evidence:row.evidence === undefined ? null : row.evidence,
    diagnostic:row.diagnostic === undefined ? null : String(row.diagnostic),
  })).sort((a,b)=>a.id.localeCompare(b.id));
}
function fingerprintInput(attestation) {
  return {
    schema_version: attestation.schema_version,
    queue_path: attestation.queue_path,
    queue_blob_oid: attestation.queue_blob_oid,
    request_id: attestation.request_id,
    event_before: attestation.event_before,
    event_after: attestation.event_after,
    protocol_head: attestation.protocol_head,
    execution_head: attestation.execution_head,
    operation_kind: attestation.operation_kind,
    mode: attestation.mode,
    bindings: attestation.bindings,
    projection_sha256: attestation.projection_sha256,
    prompt_sha256: attestation.prompt_sha256,
    prompt_file_sha256: attestation.prompt_file_sha256 || null,
    prompt_bytes: attestation.prompt_bytes,
    package_lock_sha256: attestation.package_lock_sha256,
    toolchain: attestation.toolchain,
    checks: normalizedChecks(attestation.checks),
  };
}
const REQUIRED_CHECK_IDS = Array.from({length:22}, (_, i) => 'PF-' + String(i + 1).padStart(3, '0'));
function completeChecks(checks) {
  if (!Array.isArray(checks)) return false;
  const ids = checks.map(row => row && row.id).sort();
  return JSON.stringify(ids) === JSON.stringify(REQUIRED_CHECK_IDS);
}
function derivedStatus(checks) {
  return completeChecks(checks) && checks.every(row => row.status === 'PASS' || row.status === 'NOT_APPLICABLE') ? 'PASS' : 'FAIL';
}
function verifyApplicability(attestation, queue) {
  const kind = String(queue.operation_kind || 'IMPLEMENT').toUpperCase();
  if (attestation.operation_kind !== kind || attestation.mode !== String(queue.mode || '').toUpperCase()) {
    throw new Error('PREFLIGHT_OPERATION_MISMATCH');
  }
  const notApplicable = new Set();
  if (queue.recovery_migration === undefined) notApplicable.add('PF-007');
  if (kind === 'IMPLEMENT') {
    notApplicable.add('PF-008');
    if (!queue.delivery_target) notApplicable.add('PF-015');
  }
  else if (kind === 'VISUAL_CORRECTION') { notApplicable.add('PF-009'); notApplicable.add('PF-010'); }
  else throw new Error('PREFLIGHT_OPERATION_MISMATCH');
  for (const row of attestation.checks) {
    if ((row.status === 'NOT_APPLICABLE') !== notApplicable.has(row.id)) {
      throw new Error('PREFLIGHT_CHECK_APPLICABILITY_INVALID: ' + row.id);
    }
  }
}
function computeFingerprint(attestation) {
  return sha256(fingerprintInput(attestation));
}
function finalize(attestation) {
  const checks = normalizedChecks(attestation.checks || []);
  for (const row of checks) {
    if (!CHECK_STATUSES.has(row.status)) throw new Error('PREFLIGHT_CHECK_STATUS_INVALID: ' + row.id + ':' + row.status);
  }
  const out = {
    ...attestation,
    schema_version: SCHEMA,
    checks,
    status: derivedStatus(checks),
  };
  out.preflight_fingerprint = computeFingerprint(out);
  return out;
}
function verify(attestation, expected = {}) {
  if (!attestation || attestation.schema_version !== SCHEMA) throw new Error('PREFLIGHT_ATTESTATION_SCHEMA_INVALID');
  if (!['PASS','FAIL'].includes(attestation.status)) throw new Error('PREFLIGHT_ATTESTATION_STATUS_INVALID');
  if (!completeChecks(attestation.checks)) throw new Error('PREFLIGHT_CHECK_COVERAGE_INVALID');
  if (attestation.status !== derivedStatus(attestation.checks)) throw new Error('PREFLIGHT_VERDICT_INCONSISTENT');
  for (const row of attestation.checks) {
    if (!CHECK_STATUSES.has(String(row.status))) throw new Error('PREFLIGHT_CHECK_STATUS_INVALID: ' + String(row.id));
  }
  if (expected.queue_path && attestation.queue_path !== expected.queue_path) throw new Error('PREFLIGHT_QUEUE_PATH_MISMATCH');
  if (expected.queue_blob_oid && attestation.queue_blob_oid !== expected.queue_blob_oid) throw new Error('PREFLIGHT_QUEUE_BLOB_MISMATCH');
  if (expected.request_id && attestation.request_id !== expected.request_id) throw new Error('PREFLIGHT_REQUEST_ID_MISMATCH');
  if (expected.protocol_head && attestation.protocol_head !== expected.protocol_head) throw new Error('PREFLIGHT_PROTOCOL_HEAD_MISMATCH');
  if (expected.execution_head && attestation.execution_head !== expected.execution_head) throw new Error('PREFLIGHT_EXECUTION_HEAD_MISMATCH');
  const actual = computeFingerprint(attestation);
  if (actual !== attestation.preflight_fingerprint) throw new Error('PREFLIGHT_FINGERPRINT_MISMATCH');
  return attestation;
}

module.exports = { REQUIRED_CHECK_IDS, verifyApplicability, SCHEMA, CHECK_STATUSES, canonical, sha256, computeFingerprint, finalize, verify };

'use strict';

/**
 * Contrat de la demande de file — KV2-23, structurel KV2-01.
 *
 * Ce module est la SOURCE UNIQUE du contrat Lean Queue. Le JSON Schema publié
 * en est une projection et les tests de complétude imposent qu'un champ de
 * comportement ne puisse plus être admis puis perdu avant le superviseur.
 */

const SHA40 = /^[0-9a-f]{40}$/;
const SHA64 = /^[0-9a-f]{64}$/;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const SLICE_ID = /^[A-Za-z0-9._-]{1,80}$/;
const SAFE_BRANCH = /^[A-Za-z0-9._/-]{1,200}$/;
const COMMENT_REF = /^issue_comment:[1-9][0-9]*$/;

const LEAN_REQUEST_SCHEMA = 'kodjo.protocol.v2.lean-request.0.6.13';
const CHECKS = ['jest', 'typescript', 'lint'];
const MODES = ['INITIAL', 'RESUME_DELTA'];
const OPERATION_KINDS = ['IMPLEMENT', 'VISUAL_CORRECTION'];
const RETRY_CODES = [
  'CHECKS_FAILED', 'SCOPE_VIOLATION', 'INFRASTRUCTURE', 'CLARIFICATION',
  'BUDGET_EXHAUSTED', 'CONTROLLED_INTERRUPTION_AFTER_RECOVERY', 'VISUAL_CORRECTION',
];
const MAX_RETRY_REASON_DETAIL_BYTES = 4096;
const RETRY_REASON_KEYS = Object.freeze(['code', 'detail']);

const isObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const isString = (v) => typeof v === 'string' && v.length > 0;
const LIMIT_KEYS = new Set([
  'max_ai_calls', 'max_duration_seconds', 'max_prompt_bytes',
  'max_total_prompt_bytes', 'max_rollovers',
]);

function operationKind(queue) {
  return String((queue && queue.operation_kind) || 'IMPLEMENT').toUpperCase();
}

/** Motif de reprise fermé, textuel et borné avant toute projection ou invocation. */
function validateRetryReason(value) {
  if (!isObject(value)) return 'objet structure attendu';
  const keys = Object.keys(value).sort();
  if (keys.length !== RETRY_REASON_KEYS.length ||
      RETRY_REASON_KEYS.some((key) => !keys.includes(key))) {
    return 'proprietes exactes attendues: ' + RETRY_REASON_KEYS.join(', ');
  }
  if (!RETRY_CODES.includes(value.code)) return 'code inconnu: ' + JSON.stringify(value.code);
  if (typeof value.detail !== 'string') return 'detail textuel attendu';
  if (value.detail.trim().length === 0) return 'detail textuel non vide attendu';
  const bytes = Buffer.byteLength(value.detail, 'utf8');
  if (bytes > MAX_RETRY_REASON_DETAIL_BYTES) {
    return 'detail hors limite: ' + bytes + ' octets (maximum ' + MAX_RETRY_REASON_DETAIL_BYTES + ')';
  }
  return null;
}

/** Preuve d'autorisation : objet structure, jamais chaine libre. */
function authorizationShape(fields, kinds) {
  return (value) => {
    if (!isObject(value)) return 'doit etre un objet structure, pas une chaine';
    for (const field of fields) {
      if (!isString(value[field])) return 'champ requis manquant ou vide: ' + field;
    }
    if (!kinds.includes(value.evidence_kind)) {
      return 'evidence_kind doit valoir ' + kinds.join(' ou ') + ' (recu: ' + JSON.stringify(value.evidence_kind) + ')';
    }
    return null;
  };
}

function validateDeliveryTarget(value, queue) {
  const kind = operationKind(queue);
  if (value === undefined) return kind === 'VISUAL_CORRECTION' ? 'cible EXISTING_PR requise en VISUAL_CORRECTION' : null;
  if (!['IMPLEMENT', 'VISUAL_CORRECTION'].includes(kind)) return 'operation incompatible avec delivery_target';
  if (!isObject(value)) return 'objet structure attendu';
  const keys = Object.keys(value).sort();
  const expected = ['application_head', 'application_pr', 'branch', 'kind'];
  if (keys.length !== expected.length || expected.some((key) => !keys.includes(key))) {
    return 'proprietes exactes attendues: ' + expected.join(', ');
  }
  if (value.kind !== 'EXISTING_PR') return 'kind doit valoir EXISTING_PR';
  if (!Number.isInteger(value.application_pr) || value.application_pr < 1) return 'application_pr entier >= 1 attendu';
  if (!SHA40.test(String(value.application_head || ''))) return 'application_head SHA-40 attendu';
  const branch = String(value.branch || '');
  if (!SAFE_BRANCH.test(branch) || branch.startsWith('/') || branch.endsWith('/') || branch.includes('..') || branch.includes('//')) {
    return 'branche Git canonique attendue';
  }
  return null;
}

function validateMaterializedRecovery(value, queue) {
  const kind = operationKind(queue);
  if (!isObject(value)) return 'objet structure attendu';
  const expected = ['evidence_kind', 'materialized_head', 'patch_sha256', 'source_application_head', 'source_artifact_id', 'source_run_id'];
  const keys = Object.keys(value).sort();
  if (keys.length !== expected.length || expected.some((key) => !keys.includes(key))) {
    return 'proprietes exactes attendues: ' + expected.join(', ');
  }
  if (String(queue.mode).toUpperCase() !== 'RESUME_DELTA' || kind !== 'IMPLEMENT') {
    return 'reserve a IMPLEMENT RESUME_DELTA';
  }
  if (!queue.delivery_target || queue.delivery_target.kind !== 'EXISTING_PR') {
    return 'cible EXISTING_PR requise';
  }
  if (!/^[1-9][0-9]*$/.test(String(value.source_run_id))) return 'source_run_id numerique attendu';
  if (!/^[1-9][0-9]*$/.test(String(value.source_artifact_id))) return 'source_artifact_id numerique attendu';
  if (!SHA64.test(String(value.patch_sha256 || ''))) return 'patch_sha256 SHA-256 attendu';
  if (!SHA40.test(String(value.source_application_head || ''))) return 'source_application_head SHA-40 attendu';
  if (!SHA40.test(String(value.materialized_head || ''))) return 'materialized_head SHA-40 attendu';
  if (value.evidence_kind !== 'ARTIFACT_HASH') return 'evidence_kind doit valoir ARTIFACT_HASH';
  if (String(value.source_run_id) !== String(queue.retry_of_run_id || '')) {
    return 'source_run_id doit etre egal a retry_of_run_id';
  }
  if (String(value.materialized_head).toLowerCase() !==
      String(queue.delivery_target.application_head || '').toLowerCase()) {
    return 'materialized_head doit etre egal au HEAD applicatif cible';
  }
  return null;
}

function validateDeliveryCheckpoint(value, queue) {
  const kind = operationKind(queue);
  if (value === undefined) return kind === 'VISUAL_CORRECTION' ? 'checkpoint certifie requis en VISUAL_CORRECTION' : null;
  if (kind !== 'VISUAL_CORRECTION') return 'reserve a VISUAL_CORRECTION';
  if (!isObject(value)) return 'objet structure attendu';
  const target = queue.delivery_target;
  const required = [
    'checkpoint_ref', 'application_pr', 'application_head', 'protocol_head', 'delivery_head',
    'package_run_id', 'package_artifact_id', 'attestation_blob_oid', 'evidence_kind',
  ];
  for (const field of required) {
    if (value[field] === undefined || value[field] === null) return 'champ requis manquant: ' + field;
    // Un checkpoint publié après une VISUAL_CORRECTION peut légitimement ne
    // porter aucune attestation de migration : ce chemin matérialise un
    // recovery vide sur le HEAD applicatif et ne rejoue pas la migration
    // historique. L'attestation reste obligatoire dès qu'une
    // recovery_migration est effectivement fournie.
    if (field !== 'attestation_blob_oid' && value[field] === '') return 'champ requis manquant ou vide: ' + field;
  }
  if (!COMMENT_REF.test(String(value.checkpoint_ref))) return 'checkpoint_ref issue_comment:<id> attendu';
  if (!Number.isInteger(value.application_pr) || value.application_pr < 1) return 'application_pr entier >= 1 attendu';
  if (!SHA40.test(String(value.application_head))) return 'application_head SHA-40 attendu';
  if (!SHA40.test(String(value.protocol_head))) return 'protocol_head SHA-40 attendu';
  if (!SHA40.test(String(value.delivery_head))) return 'delivery_head SHA-40 attendu';
  if (!/^[1-9][0-9]*$/.test(String(value.package_run_id))) return 'package_run_id numerique attendu';
  if (!/^[1-9][0-9]*$/.test(String(value.package_artifact_id))) return 'package_artifact_id numerique attendu';
  const checkpointAttestation = String(value.attestation_blob_oid || '');
  if (checkpointAttestation && !SHA40.test(checkpointAttestation)) return 'attestation_blob_oid SHA-40 attendu';
  if (queue.recovery_migration) {
    const migrationAttestation = String(queue.recovery_migration.attestation_blob_oid || '');
    if (!checkpointAttestation) return 'attestation_blob_oid requis lorsque recovery_migration est present';
    if (checkpointAttestation.toLowerCase() !== migrationAttestation.toLowerCase()) {
      return 'attestation_blob_oid doit correspondre a recovery_migration';
    }
  }
  if (value.evidence_kind !== 'ORGANISATIONAL') return 'evidence_kind doit valoir ORGANISATIONAL';
  if (String(value.protocol_head).toLowerCase() !== String(queue.source_head || '').toLowerCase()) {
    return 'protocol_head doit etre egal a source_head';
  }
  if (!target || value.application_pr !== target.application_pr ||
      String(value.application_head).toLowerCase() !== String(target.application_head || '').toLowerCase()) {
    return 'checkpoint et cible EXISTING_PR incoherents';
  }
  if (String(value.delivery_head).toLowerCase() !== String(value.application_head).toLowerCase()) {
    return 'delivery_head doit etre egal au HEAD applicatif certifie avant correction';
  }
  return null;
}

const PROPERTIES = {
