  session_id: {
    nature: 'BEHAVIOUR', required: 'always', type: ['string', 'null'],
    validate: (v, q) => {
      if (String(q.mode).toUpperCase() === 'INITIAL') return v === null ? null : 'doit etre null en INITIAL';
      return UUID.test(String(v || '')) ? null : 'UUID attendu en RESUME_DELTA';
