      // JSON.stringify must see both halves of a valid surrogate pair.
      if (end < text.length && /[\uD800-\uDBFF]/.test(text[end - 1])
          && /[\uDC00-\uDFFF]/.test(text[end])) end -= 1;
      emit(JSON.stringify(text.slice(start, end)).slice(1, -1));
      start = end;
    }
    emit('"');
  };
